css:
.riskdesk-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e6ecf5;
    background: radial-gradient(120% 120% at 0% 0%, #11203a 0%, #0a1424 55%, #060d18 100%);
    border-radius: 18px;
    box-shadow: inset 0 0 0 1px rgba(120, 160, 220, 0.08);
}

.riskdesk-container * {
    box-sizing: border-box;
}

.riskdesk-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #0f2748 0%, #14365f 55%, #1d4a7a 100%);
    color: #f1f6ff;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid rgba(120, 170, 240, 0.18);
    box-shadow: 0 12px 34px rgba(2, 10, 24, 0.55);
}

.riskdesk-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.riskdesk-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.4px;
    font-weight: 700;
    color: #9fd0ff;
    background: rgba(120, 180, 255, 0.10);
    border: 1px solid rgba(120, 180, 255, 0.22);
    padding: 5px 14px;
    border-radius: 999px;
}

.riskdesk-subtitle {
    margin: 12px auto 0;
    max-width: 780px;
    font-size: 1rem;
    line-height: 1.55;
    color: #c7d6ec;
}

.riskdesk-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #aebfd8;
    margin-bottom: 18px;
}

.riskdesk-period-counter #currentDay,
.riskdesk-period-counter #maxPeriods {
    font-weight: 800;
    color: #6fb1ff;
}

.riskdesk-round-name {
    background: rgba(111, 177, 255, 0.14);
    color: #cfe4ff;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    letter-spacing: 0.4px;
}

.riskdesk-clock {
    margin-left: auto;
    color: #ffb84d;
    font-weight: 700;
    font-size: 0.86rem;
    letter-spacing: 0.3px;
}

.riskdesk-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.riskdesk-status-card {
    background: linear-gradient(160deg, #14263f 0%, #0e1c33 100%);
    border: 1px solid rgba(120, 160, 220, 0.14);
    border-radius: 14px;
    padding: 16px 16px 14px;
    text-align: center;
    box-shadow: 0 6px 18px rgba(2, 10, 24, 0.4);
}

.riskdesk-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #8fa4c4;
    margin-bottom: 6px;
}

.riskdesk-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.05;
    color: #ffffff;
}

.riskdesk-sublabel {
    font-size: 0.72rem;
    color: #8294b3;
    margin-top: 6px;
    line-height: 1.3;
}

.riskdesk-card-quality .riskdesk-value { color: #6fb1ff; }
.riskdesk-card-ev .riskdesk-value { color: #43d6a3; }
.riskdesk-card-regret .riskdesk-value { color: #ffb84d; }
.riskdesk-card-covenant .riskdesk-value { color: #e8eef8; }

.riskdesk-card-covenant.riskdesk-covenant-breach {
    border-color: rgba(255, 90, 90, 0.55);
    box-shadow: 0 0 0 1px rgba(255, 90, 90, 0.4), 0 6px 18px rgba(120, 10, 10, 0.4);
}
.riskdesk-card-covenant.riskdesk-covenant-breach .riskdesk-value { color: #ff6b6b; }
.riskdesk-card-covenant.riskdesk-covenant-safe .riskdesk-value { color: #43d6a3; }

.riskdesk-budget-bar {
    display: flex;
    align-items: center;
    gap: 12px;
    flex-wrap: wrap;
    background: rgba(20, 38, 63, 0.7);
    border: 1px solid rgba(120, 160, 220, 0.14);
    border-radius: 12px;
    padding: 10px 16px;
    margin-bottom: 18px;
    font-size: 0.9rem;
}

.riskdesk-budget-label { color: #8fa4c4; font-weight: 600; }
.riskdesk-budget-bar #budgetDisplay { font-weight: 800; color: #43d6a3; font-size: 1.05rem; }
.riskdesk-sunk { margin-left: auto; color: #ff9d6b; font-weight: 600; font-size: 0.82rem; }

.riskdesk-briefing {
    display: flex;
    gap: 16px;
    align-items: flex-start;
    background: linear-gradient(160deg, #16304f 0%, #0f2138 100%);
    border: 1px solid rgba(120, 170, 240, 0.16);
    border-left: 4px solid #6fb1ff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
}

.riskdesk-briefing-icon { font-size: 1.9rem; line-height: 1; }
.riskdesk-briefing-body { flex: 1; }

.riskdesk-briefing-title {
    font-size: 1.12rem;
    font-weight: 800;
    color: #ffffff;
    margin-bottom: 8px;
}

.riskdesk-briefing-text {
    font-size: 0.95rem;
    line-height: 1.6;
    color: #c7d6ec;
}

.riskdesk-briefing-text strong { color: #9fd0ff; }
.riskdesk-briefing-text em { color: #ffb84d; font-style: normal; font-weight: 600; }

.riskdesk-pathcard-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
    margin-bottom: 18px;
}

.riskdesk-pathcard {
    background: rgba(15, 30, 51, 0.85);
    border: 1px solid rgba(120, 160, 220, 0.14);
    border-radius: 12px;
    padding: 12px 14px;
}

.riskdesk-path-a { border-top: 3px solid #ff6b6b; }
.riskdesk-path-b { border-top: 3px solid #43d6a3; }
.riskdesk-path-c { border-top: 3px solid #8fa4c4; }

.riskdesk-pathcard-title {
    font-weight: 800;
    font-size: 0.9rem;
    color: #e6ecf5;
    margin-bottom: 4px;
}

.riskdesk-pathcard-cost {
    font-size: 0.78rem;
    color: #93a6c4;
    line-height: 1.4;
    font-variant-numeric: tabular-nums;
}

.riskdesk-controls {
    background: linear-gradient(160deg, #122236 0%, #0c1828 100%);
    border: 1px solid rgba(120, 160, 220, 0.14);
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
}

.riskdesk-controls h3 {
    font-size: 1.05rem;
    font-weight: 800;
    color: #ffffff;
    margin: 0 0 16px;
    letter-spacing: 0.2px;
}

.riskdesk-panel label {
    display: block;
    font-weight: 600;
    font-size: 0.9rem;
    color: #cfdcef;
    margin: 14px 0 6px;
    line-height: 1.45;
}

.riskdesk-panel label:first-child { margin-top: 0; }

.riskdesk-container select,
.riskdesk-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border-radius: 9px;
    border: 1px solid rgba(120, 160, 220, 0.28);
    background-color: #0c1a2e;
    color: #eaf1fb;
    font-size: 0.92rem;
    font-family: inherit;
}

.riskdesk-container select option {
    background-color: #0c1a2e;
    color: #eaf1fb;
}

.riskdesk-container select:focus,
.riskdesk-container input[type="number"]:focus {
    outline: none;
    border-color: #6fb1ff;
    box-shadow: 0 0 0 3px rgba(111, 177, 255, 0.2);
}

.riskdesk-container input[type="range"] {
    width: 100%;
    accent-color: #6fb1ff;
    margin: 6px 0 2px;
}

.riskdesk-hint {
    font-size: 0.8rem;
    color: #8294b3;
    line-height: 1.45;
    margin-top: 5px;
}

.riskdesk-range-readout {
    font-size: 0.84rem;
    color: #aebfd8;
    margin-top: 4px;
}
.riskdesk-range-readout #criterionReadout {
    font-weight: 800;
    color: #6fb1ff;
}

.riskdesk-signal {
    background: linear-gradient(135deg, #3a1c12 0%, #2a160d 100%);
    border: 1px solid rgba(255, 150, 80, 0.4);
    border-left: 4px solid #ff9d4d;
    border-radius: 10px;
    padding: 12px 14px;
    margin-bottom: 14px;
    font-size: 0.88rem;
    line-height: 1.5;
    color: #ffd9b3;
    font-weight: 600;
}

.riskdesk-interim {
    background: linear-gradient(135deg, #12233a 0%, #0e1b2e 100%);
    border-color: rgba(111, 177, 255, 0.4);
    border-left-color: #6fb1ff;
    color: #d6e6ff;
}

.riskdesk-controls .btn-primary {
    margin-top: 20px;
    background: linear-gradient(135deg, #2f7fe0 0%, #1d62c4 100%);
    border: none;
    font-weight: 700;
    padding: 11px 26px;
    border-radius: 10px;
    letter-spacing: 0.3px;
    box-shadow: 0 6px 16px rgba(29, 98, 196, 0.4);
}
.riskdesk-controls .btn-primary:hover {
    background: linear-gradient(135deg, #3a8af0 0%, #2670d4 100%);
}

.riskdesk-controls .btn-outline-secondary {
    margin-top: 20px;
    margin-left: 10px;
    color: #aebfd8;
    border-color: rgba(120, 160, 220, 0.4);
    font-weight: 600;
}
.riskdesk-controls .btn-outline-secondary:hover {
    background: rgba(120, 160, 220, 0.12);
    color: #eaf1fb;
}

.riskdesk-coach {
    background: linear-gradient(160deg, #1a1330 0%, #120d22 100%);
    border: 1px solid rgba(170, 140, 240, 0.22);
    border-left: 4px solid #a98cf0;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
}

.riskdesk-coach-header {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 800;
    color: #c4aef5;
    margin-bottom: 8px;
}

.riskdesk-coach-body {
    font-size: 0.95rem;
    line-height: 1.6;
    color: #ddd2f5;
}
.riskdesk-coach-body strong { color: #d9c6ff; }

.riskdesk-history {
    background: linear-gradient(160deg, #122236 0%, #0c1828 100%);
    border: 1px solid rgba(120, 160, 220, 0.14);
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
}

.riskdesk-history h3,
.riskdesk-chart h3 {
    font-size: 1.05rem;
    font-weight: 800;
    color: #ffffff;
    margin: 0 0 14px;
}

.riskdesk-history table {
    width: 100%;
    color: #cfdcef;
    font-size: 0.86rem;
    border-collapse: collapse;
}

.riskdesk-history table th {
    color: #8fa4c4;
    text-transform: uppercase;
    font-size: 0.7rem;
    letter-spacing: 0.6px;
    border-bottom: 1px solid rgba(120, 160, 220, 0.2);
    padding: 8px 6px;
    text-align: left;
}

.riskdesk-history table td {
    border-bottom: 1px solid rgba(120, 160, 220, 0.08);
    padding: 8px 6px;
    font-variant-numeric: tabular-nums;
}

.riskdesk-chart {
    background: linear-gradient(160deg, #122236 0%, #0c1828 100%);
    border: 1px solid rgba(120, 160, 220, 0.14);
    border-radius: 14px;
    padding: 18px 20px 22px;
}

@media (max-width: 768px) {
    .riskdesk-container { padding: 16px; }
    .riskdesk-header h1 { font-size: 1.7rem; }
    .riskdesk-status-cards { grid-template-columns: repeat(2, 1fr); }
    .riskdesk-pathcard-grid { grid-template-columns: 1fr; }
    .riskdesk-value { font-size: 2rem; }
    .riskdesk-clock { margin-left: 0; width: 100%; }
    .riskdesk-sunk { margin-left: 0; width: 100%; }
    .riskdesk-controls .btn-outline-secondary { margin-left: 0; display: block; width: 100%; }
}


/* ---- v1.1.0 completion / debrief screen ---- */
.rd-completion { padding: 8px 4px 4px; }
.rd-cm-head { text-align: center; margin-bottom: 16px; }
.rd-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #6fb1ff; }
.rd-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #8fa4c4; }
.rd-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #e7eefb; }
.rd-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.rd-cm-yes { background: rgba(67,214,163,0.16); color: #43d6a3; border: 1px solid rgba(67,214,163,0.45); }
.rd-cm-no { background: rgba(255,111,111,0.14); color: #ff8c8c; border: 1px solid rgba(255,111,111,0.5); }
.rd-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.rd-cm-metric { flex: 1 1 120px; min-width: 108px; background: rgba(111,177,255,0.08); border: 1px solid rgba(111,177,255,0.22); border-radius: 10px; padding: 10px 8px; text-align: center; }
.rd-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #6fb1ff; }
.rd-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #8fa4c4; text-transform: uppercase; letter-spacing: 0.03em; }
.rd-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #e7eefb; }
.rd-cm-insights { margin: 0; padding-left: 20px; }
.rd-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #cdd8ea; }

