(function() {
    'use strict';

    class RiskAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Decide Under Risk`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // €90M discretionary envelope; €22M already sunk into the in-house SiC program.
            this.ENVELOPE = 90;
            this.SUNK = 22;
            this.COVENANT_LIMIT = 3.0;

            // The concept's disclosed odds (gross NPV outcomes, €M) and incremental spend.
            // Path A escalate in-house: 55%/30%/15% (pre-signal); spend €60M.
            // Path B license:          85%/15%; spend €45M.
            // Path C walk away:         certain; spend €0M.
            this.PATHS = {
                A: { spend: 60, states: [{ p: 0.55, npv: 130 }, { p: 0.30, npv: 25 }, { p: 0.15, npv: -70 }] },
                B: { spend: 45, states: [{ p: 0.85, npv: 70 }, { p: 0.15, npv: -10 }] },
                C: { spend: 0,  states: [{ p: 1.00, npv: 15 }] }
            };
            // Post-leak signal: Path A on-time probability falls 55% -> 45%; the 10 points
            // shift to the 9-month slip outcome (so failure prob stays 15%).
            this.PATH_A_SIGNAL = [{ p: 0.45, npv: 130 }, { p: 0.40, npv: 25 }, { p: 0.15, npv: -70 }];

            // Decision-sciences truths the committee should reach.
            this.TRUE_TOP_EV = `A`;        // Path A maximizes EV.
            this.TRUE_MIN_REGRET = `B`;    // Path B minimizes anticipated regret.
            this.TRUE_MAX_REGRET = `A`;    // Path A carries the largest maximum regret.
            this.TRUE_BREACH = `A`;        // Only Path A's worst state breaches 3.0x.

            // Worst-case net-debt/EBITDA by committed path (illustrative, from concept: A worst -> 3.1x).
            this.WORST_COVENANT = { A: 3.1, B: 2.4, C: 1.8, hedge: 3.1 };
        }

        // Probability-weighted NPV of a path, NET of its incremental spend (€M). Pure helper.
        _ev(pathKey, statesOverride) {
            const path = this.PATHS[pathKey];
            if (!path) return 0;
            const states = statesOverride || path.states;
            let gross = 0;
            states.forEach((s) => { gross += s.p * s.npv; });
            return Math.round((gross - path.spend) * 10) / 10;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    quality: 50,
                    ev: 0,
                    regret: 0,
                    covenant: this.COVENANT_LIMIT,
                    committed: ``,
                    aspiration: 0,
                    budgetUsed: 0,
                    breached: false,
                    flinched: false,
                    sunkTrapped: false,
                    qualityHistory: [50],
                    evHistory: [0],
                    regretHistory: [0],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    aspiration: 0,
                    anchor: `board`,
                    topEv: `A`,
                    minRegret: `B`,
                    maxRegret: `A`,
                    breach: `A`,
                    criterion: 50,
                    commit: `B`,
                    trigger: `preset`,
                    deadline: `binding`,
                    escalate: `cut`,
                    sunk: `ignore`,
                    defend: `trail`,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const asp = document.getElementById(`aspirationInput`);
                const anchor = document.getElementById(`anchorInput`);
                const topEv = document.getElementById(`topEvInput`);
                if (asp) decisions.aspiration = parseFloat(asp.value);
                if (anchor) decisions.anchor = anchor.value;
                if (topEv) decisions.topEv = topEv.value;
                if (!Number.isFinite(decisions.aspiration) || decisions.aspiration < -70 || decisions.aspiration > 130) {
                    warn(`warn_aspiration_range`); return false;
                }
            } else if (round === 2) {
                const mr = document.getElementById(`minRegretInput`);
                const xr = document.getElementById(`maxRegretInput`);
                const br = document.getElementById(`breachInput`);
                const cr = document.getElementById(`criterionInput`);
                if (mr) decisions.minRegret = mr.value;
                if (xr) decisions.maxRegret = xr.value;
                if (br) decisions.breach = br.value;
                if (cr) decisions.criterion = parseInt(cr.value, 10);
                if (!Number.isFinite(decisions.criterion) || decisions.criterion < 0 || decisions.criterion > 100) {
                    warn(`warn_criterion_range`); return false;
                }
            } else if (round === 3) {
                const cm = document.getElementById(`commitInput`);
                const tg = document.getElementById(`triggerInput`);
                const dl = document.getElementById(`deadlineInput`);
                if (cm) decisions.commit = cm.value;
                if (tg) decisions.trigger = tg.value;
                if (dl) decisions.deadline = dl.value;
                if (!decisions.commit) { warn(`warn_commit_required`); return false; }
            } else if (round === 4) {
                const es = document.getElementById(`escalateInput`);
                const sk = document.getElementById(`sunkInput`);
                const df = document.getElementById(`defendInput`);
                const cv = document.getElementById(`convictionInput`);
                if (es) decisions.escalate = es.value;
                if (sk) decisions.sunk = sk.value;
                if (df) decisions.defend = df.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let qualityDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            // EVs for reference (net of spend).
            const evA = this._ev(`A`);
            const evB = this._ev(`B`);
            const evC = this._ev(`C`);
            const evASignal = this._ev(`A`, this.PATH_A_SIGNAL);

            if (round === 1) {
                // Set the aspiration and compute EV. The reference point IS the decision frame
                // (Common Error 1). A board-anchored aspiration earns the most; "avoid any loss"
                // makes Path A's 15% write-off look fatal and biases away from the mandate.
                ds.aspiration = d.aspiration;

                if (d.anchor === `board`) { qualityDelta += 16; coachKey = `coach_r1_board`; }
                else if (d.anchor === `breakeven`) { qualityDelta += 6; coachKey = `coach_r1_breakeven`; }
                else if (d.anchor === `maxev`) { qualityDelta -= 6; coachKey = `coach_r1_maxev`; }
                else if (d.anchor === `avoidloss`) { qualityDelta -= 10; coachKey = `coach_r1_avoidloss`; }

                // Correctly identifying the highest-EV path (Path A) shows EV was actually computed.
                if (d.topEv === this.TRUE_TOP_EV) { qualityDelta += 10; }
                else { qualityDelta -= 8; coachKey = (coachKey === `coach_r1_board`) ? `coach_r1_noev` : coachKey; }

                // A coherent aspiration sits near the board's reference (secure the upside, survive
                // the downside) — roughly between break-even and the slip outcome. Drawing it at
                // the max payoff or far below the write-off is incoherent.
                if (d.aspiration >= 10 && d.aspiration <= 40) { qualityDelta += 8; }
                else if (d.aspiration > 100) { qualityDelta -= 6; }

                ds.ev = (d.topEv === `A`) ? evA : (d.topEv === `B`) ? evB : evC;
                summaryKey = (d.anchor === `board` && d.topEv === `A`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Build the regret matrix. Min regret = B, max regret = A, only A breaches.
                let right = 0;
                if (d.minRegret === this.TRUE_MIN_REGRET) { qualityDelta += 10; right++; }
                else { qualityDelta -= 6; }
                if (d.maxRegret === this.TRUE_MAX_REGRET) { qualityDelta += 10; right++; }
                else { qualityDelta -= 6; }
                if (d.breach === this.TRUE_BREACH) { qualityDelta += 10; right++; }
                else { qualityDelta -= 6; coachKey = `coach_r2_covenant`; }

                if (right === 3) coachKey = `coach_r2_sharp`;
                else if (right >= 1 && coachKey === `coach_default`) coachKey = `coach_r2_partial`;
                else if (right === 0) coachKey = `coach_r2_wrong`;

                // The committee must SEE the divergence: max-EV (A) and min-regret (B) point
                // to different paths. Leaning to the extremes is fine if it's deliberate; an
                // exact-50 "split the difference" with both diagnoses wrong is just indecision.
                if (right === 3 && (d.criterion <= 20 || d.criterion >= 80)) { qualityDelta += 6; coachKey = `coach_r2_deliberate`; }
                else if (right <= 1 && d.criterion === 50) { qualityDelta -= 4; }

                // Anticipated (expected) regret of the EV-max path A: in each state, regret =
                // best-achievable-in-that-state minus A's payoff. Surfacing it raises the regret KPI.
                // Best in 'A-wins' state = A(130); in 'slip' state = B(70); in 'fail' state = B(70).
                const regretA = Math.round((0.30 * (70 - 25) + 0.15 * (70 - (-70))) * 10) / 10; // = €34.5M
                ds.regret = regretA;

                summaryKey = (right === 3) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Commit under the deadline, post-signal. Track the committed path, budget and covenant.
                ds.committed = d.commit;

                if (d.commit === `A`) {
                    ds.budgetUsed = this.PATHS.A.spend;
                    ds.ev = evASignal; // re-priced at 45%
                } else if (d.commit === `B`) {
                    ds.budgetUsed = this.PATHS.B.spend;
                    ds.ev = evB;
                } else if (d.commit === `C`) {
                    ds.budgetUsed = 0;
                    ds.ev = evC;
                } else if (d.commit === `hedge`) {
                    ds.budgetUsed = 75; // license + continue R&D
                    // Hedge EV: license qualifies (B-like) AND R&D may still land, but the combined
                    // spend dominates and the worst state still breaches the covenant.
                    ds.ev = Math.round((evB + evASignal * 0.4) * 10) / 10;
                }

                ds.covenant = this.WORST_COVENANT[d.commit] || this.COVENANT_LIMIT;
                if (ds.covenant > this.COVENANT_LIMIT) ds.breached = true;

                // Trigger discipline (Common Error 5): a pre-set threshold beats reacting to anxiety.
                if (d.trigger === `preset`) { qualityDelta += 14; }
                else if (d.trigger === `react`) { qualityDelta -= 8; ds.flinched = true; coachKey = `coach_r3_flinch`; }
                else if (d.trigger === `ignore`) { qualityDelta -= 6; coachKey = `coach_r3_ignore`; }

                // Deadline realism (Common Error 6).
                if (d.deadline === `binding`) { qualityDelta += 8; }
                else { qualityDelta -= 10; coachKey = `coach_r3_deadline`; }

                // Path-specific consequences of the commitment.
                if (d.commit === `hedge`) {
                    qualityDelta -= 16; coachKey = `coach_r3_hedge`;
                } else if (d.commit === `A`) {
                    // Holding A after the signal is defensible IF the trigger was pre-set and the
                    // committee accepted the re-priced odds; otherwise it reads as sunk-cost inertia.
                    if (d.trigger === `preset`) { qualityDelta += 4; coachKey = `coach_r3_holdA`; }
                    else { qualityDelta -= 6; coachKey = `coach_r3_inertiaA`; }
                } else if (d.commit === `B`) {
                    if (d.trigger === `preset`) { qualityDelta += 8; coachKey = `coach_r3_switchB`; }
                    else { coachKey = `coach_r3_flinchB`; }
                } else if (d.commit === `C`) {
                    qualityDelta -= 4; coachKey = `coach_r3_walk`;
                }

                summaryKey = (d.commit === `hedge`) ? `sum_r3_hedge`
                    : (d.commit === `C`) ? `sum_r3_walk`
                    : (d.trigger === `preset` ? `sum_r3_good` : `sum_r3_weak`);
            } else if (round === 4) {
                // Escalate or cut losses, then defend. The committed path produced an interim result.
                const committed = ds.committed || d.commit;

                // Sunk-cost discipline (Common Error 2) — the single most heavily weighted lever.
                if (d.sunk === `ignore`) { qualityDelta += 16; }
                else { qualityDelta -= 16; ds.sunkTrapped = true; coachKey = `coach_r4_sunk`; }

                // Escalate-or-cut on a turned bet. If the in-house path slipped, "one more push"
                // is escalation of commitment; cutting losses is the hygienic move.
                if (committed === `A` || committed === `hedge`) {
                    if (d.escalate === `push`) { qualityDelta -= 12; coachKey = `coach_r4_push`; }
                    else if (d.escalate === `cut`) { qualityDelta += 12; if (coachKey === `coach_default`) coachKey = `coach_r4_cut`; }
                    else { qualityDelta += 2; }
                } else if (committed === `B`) {
                    // On B, a rejection invites renegotiation; cutting or holding both reasonable.
                    if (d.escalate === `push`) { qualityDelta -= 4; }
                    else { qualityDelta += 8; if (coachKey === `coach_default`) coachKey = `coach_r4_renegotiate`; }
                } else {
                    if (d.escalate === `hold`) { qualityDelta += 4; }
                }

                // Defending on process (the decision trail) vs outcome/luck or the champion's conviction.
                if (d.defend === `trail`) { qualityDelta += 14; if (coachKey === `coach_default`) coachKey = `coach_r4_trail`; }
                else if (d.defend === `outcome`) { qualityDelta -= 10; coachKey = `coach_r4_outcome`; }
                else if (d.defend === `champion`) { qualityDelta -= 8; coachKey = `coach_r4_champion`; }

                // Conviction in separating process from luck nudges quality.
                qualityDelta += Math.round((d.conviction - 60) / 8);

                summaryKey = (d.sunk === `ignore` && d.defend === `trail`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply deltas with clamps.
            ds.quality = Math.max(0, Math.min(100, ds.quality + qualityDelta));
            if (round === 1 || round === 3) {
                ds.ev = Math.round(ds.ev * 10) / 10;
            }

            ds.qualityHistory.push(Math.round(ds.quality));
            ds.evHistory.push(Math.round(ds.ev));
            ds.regretHistory.push(Math.round(ds.regret));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose the decision-quality score (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            // ds.quality is the authoritative composite; the final period locks the grade.
            ds.performance = { overallScore: Math.round(ds.quality) };

            return {
                period: state.currentPeriod,
                quality: Math.round(ds.quality),
                qualityDelta: Math.round(qualityDelta),
                ev: Math.round(ds.ev),
                regret: Math.round(ds.regret),
                covenant: ds.covenant,
                breached: ds.breached,
                committed: ds.committed,
                budgetUsed: ds.budgetUsed,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

