                if (card) {
                    card.classList.toggle(`riskdesk-covenant-breach`, Number(v) > this.COVENANT_LIMIT);
                    card.classList.toggle(`riskdesk-covenant-safe`, Number(v) <= this.COVENANT_LIMIT);
                }
