        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.qualityHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            return {
                riskChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.qualityHistory },
                        { data: ds.evHistory },
                        { data: ds.regretHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const quality = Math.round(ds.quality);
            const ev = Math.round(ds.ev);
            const regret = Math.round(ds.regret);
            const covenantHeld = !ds.breached;

            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };

            // Grade band -> localized label (thresholds identical to v1.0.0).
            let performanceKey = `grade_gambler`;
            if (quality >= 78 && covenantHeld && !ds.sunkTrapped && !ds.flinched) performanceKey = `grade_hygiene`;
            else if (quality >= 64 && covenantHeld) performanceKey = `grade_sound`;
            else if (quality >= 48) performanceKey = `grade_mixed`;
            else if (!covenantHeld) performanceKey = `grade_breach`;
            const performance = T(performanceKey);

            const insights = [];
            if (performanceKey === `grade_hygiene`) insights.push(window.mySimulation.t(`insight_hygiene`));
            else if (!covenantHeld) insights.push(window.mySimulation.t(`insight_breach`));
            else insights.push(window.mySimulation.t(`insight_partial`));

            if (ds.sunkTrapped) insights.push(window.mySimulation.t(`insight_sunk`));
            if (ds.flinched) insights.push(window.mySimulation.t(`insight_flinch`));
            if (ds.committed === `hedge`) insights.push(window.mySimulation.t(`insight_hedge`));
            if (quality >= 70 && !ds.sunkTrapped && !ds.flinched) insights.push(window.mySimulation.t(`insight_consistent`));

            return {
                quality: quality,
                ev: ev,
                regret: regret,
                covenantHeld: covenantHeld,
                committed: ds.committed,
                sunkTrapped: !!ds.sunkTrapped,
                flinched: !!ds.flinched,
                totalScore: quality,
                overallScore: quality,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.totalScore === 'number') ? s.totalScore
                : (typeof s.overallScore === 'number' ? s.overallScore
                : (typeof s.quality === 'number' ? s.quality : 0));
            var grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            var held = !!s.covenantHeld;
            var badge = held
                ? '<span class="rd-cm-badge rd-cm-yes">' + T('cm_covenant_held') + '</span>'
                : '<span class="rd-cm-badge rd-cm-no">' + T('cm_covenant_breached') + '</span>';
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var evVal = Math.round(s.ev || 0);
            var evStr = (evVal >= 0 ? '\u20AC' : '\u2212\u20AC') + Math.abs(evVal) + 'M';
            var metrics = ''
                + '<div class="rd-cm-metric"><span class="rd-cm-mv">' + Math.round(s.quality||0) + '</span><span class="rd-cm-ml">' + T('cm_m_quality') + '</span></div>'
                + '<div class="rd-cm-metric"><span class="rd-cm-mv">' + evStr + '</span><span class="rd-cm-ml">' + T('cm_m_ev') + '</span></div>'
                + '<div class="rd-cm-metric"><span class="rd-cm-mv">\u20AC' + Math.round(s.regret||0) + 'M</span><span class="rd-cm-ml">' + T('cm_m_regret') + '</span></div>'
                + '<div class="rd-cm-metric"><span class="rd-cm-mv">' + (held ? T('cm_held_short') : T('cm_breached_short')) + '</span><span class="rd-cm-ml">' + T('cm_m_covenant') + '</span></div>';
            return ''
                + '<div class="rd-completion">'
                +   '<div class="rd-cm-head">'
                +     '<div class="rd-cm-score">' + score + '<span class="rd-cm-score-max">/100</span></div>'
                +     '<div class="rd-cm-grade">' + grade + ' ' + badge + '</div>'
                +   '</div>'
                +   '<div class="rd-cm-metrics">' + metrics + '</div>'
                +   '<div class="rd-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="rd-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.breached) return window.mySimulation.t(`hint_covenant`);
            if (ds.sunkTrapped) return window.mySimulation.t(`hint_sunk`);
            if (ds.flinched) return window.mySimulation.t(`hint_flinch`);
            if (ds.quality < 40 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_quality`);
            if (ds.quality >= 70 && !ds.breached) return window.mySimulation.t(`hint_strong`);
            return null;
        }

