                    warn_aspiration_range:  `Tu línea de aspiración debe ser una cifra de VAN entre −70M € y +130M €.`,
                    warn_criterion_range:   `Tu inclinación VE-frente-a-arrepentimiento debe estar entre 0 y 100.`,
